<section class="mx-auto max-w-7xl px-4 py-14 lg:px-8"><div class="mb-8"><p class="font-bold text-accent">Smart Search</p><h1 class="font-display text-5xl font-black">Marketplace Catalog</h1><form class="mt-6 grid gap-3 md:grid-cols-[1fr_240px_140px]" method="get"><input type="hidden" name="route" value="catalog"><input name="q" value="<?= e($search) ?>" class="rounded-2xl border border-white/10 bg-white/5 p-4" placeholder="Search by keyword"><select name="category" class="rounded-2xl border border-white/10 bg-[#111827] p-4"><option value="">All categories</option><?php foreach ($categories as $category): ?><option value="<?= e($category['slug']) ?>" <?= ($_GET['category'] ?? '') === $category['slug'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><button class="neon-btn rounded-2xl font-black">Filter</button></form></div><div class="grid gap-6 sm:grid-cols-2 xl:grid-cols-4"><?php foreach ($products as $product) require APP_ROOT . '/views/partials/product-card.php'; ?></div></section>
